function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function modal(title,body,submit){$('#dialog').innerHTML=`<div class="dialog-head"><h2>${h(title)}</h2>${button('✕','close','','','aria-label="關閉"')}</div>${submit?'<form id="modal-form">':''}${body}<p class="error" id="dialog-error"></p>${submit?'<div class="actions dialog-actions"><button type="button" data-act="close">取消</button><button class="primary" type="submit">儲存</button></div></form>':''}`;if(!$('#dialog').open)$('#dialog').showModal();if(submit)$('#modal-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,submitButton=form.querySelector('[type=submit]');submitButton.disabled=true;try{await submit(new FormData(form),form);$('#dialog').close();}catch(e){$('#dialog-error').textContent=e.message;if(e.liveSongId)$('#dialog-error').insertAdjacentHTML('beforeend','<div class="actions">'+button('前往現點','request',e.liveSongId,'primary','data-kind="live"')+'</div>');}finally{submitButton.disabled=false;}};}
