function paginate(items,key,size=10){const max=Math.max(1,Math.ceil(items.length/size));pages[key]=Math.min(Math.max(1,pages[key]||1),max);return {rows:items.slice((pages[key]-1)*size,pages[key]*size),nav:`<div class="pagination">${button('上一頁','page',key,'tiny',`data-step="-1" ${pages[key]===1?'disabled':''}`)}<label class="page-jump">第 <input type="number" min="1" max="${max}" value="${pages[key]}" data-page-key="${h(key)}" aria-label="輸入頁碼"> / ${max} 頁</label>${button('跳頁','jumpPage',key)}${button('下一頁','page',key,'tiny',`data-step="1" ${pages[key]===max?'disabled':''}`)}</div>`};}
async function api(body){if(admin&&(isAdmin()||body.management)&&!admin.legacy&&admin.accessUntil<Date.now()&&body.op!=='refreshAdmin'){const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json',apikey:PUBLISHABLE_KEY},body:JSON.stringify({op:'refreshAdmin',refreshToken:admin.refreshToken})}),v=await r.json();if(!r.ok)throw new Error(v.error||'請重新登入管理');admin={...admin,...v,accessUntil:Date.now()+(v.expiresIn-60)*1000};put('admin',admin);}const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json',apikey:PUBLISHABLE_KEY},body:JSON.stringify({streamer:streamerSlug,token:(isAdmin()||body.management)?admin?.token:session?.token,signatures,...body})});const data=await r.json();if(!r.ok||data.error)throw new Error(data.error||'連線失敗');if(data.signatures)signatures=data.signatures;if(data.now)offset=timeValue(data.now)-Date.now();return data;}
async function refresh(force=false){if(busy)return;if(demo||draft&&isAdmin()){full=(draft&&isAdmin()?draft.state:null)||get('demo')||full;state=publicView(full,actor(),clock(),streamerSlug);render();return;}const r=await api({op:'read',revision:force?-1:state.revision});if(r.state){state={...state,...r.state};render();}if(!r.ready&&!isAdmin())$('#app').innerHTML=`<section class="card"><h2>歌本整理中 ♡</h2><p>管理員完成資料移轉後就能開始點歌。</p>${button('管理入口','admin')}</section>`;}
