let querySequence=0;
const composingInputs=new WeakSet();
document.addEventListener('compositionstart',e=>{composingInputs.add(e.target);if(e.target.id==='login-query')querySequence++;});
document.addEventListener('compositionend',e=>{composingInputs.delete(e.target);updateSearch(e.target);});
document.addEventListener('input',e=>{if(!e.isComposing&&!composingInputs.has(e.target))updateSearch(e.target);});
async function updateSearch(input){const id=input.id;try{
 if(input.matches('[data-entity-query]')){const box=input.closest('.entity-picker');box.querySelector('[type=hidden]').value='';showEntityResults(box);}
 if(id==='login-query'){const seq=++querySequence,q=input.value,rows=demo?playerSearch(full,q).slice(0,20):(await api({op:'search',query:q})).players;if(seq!==querySequence||!$('#login-results'))return;$('#login-results').innerHTML=q?rows.map(p=>`<div class="song"><div class="info"><b>${h(p.name)}</b><small>${h(p.ids.join('、'))}</small></div>${button('登入','chooseLogin',p.playerId)}</div>`).join('')||blank('找不到玩家'):'';}
 if(id==='home-search')$('#home-results').innerHTML=input.value?songRows(state.songs.filter(s=>matchesSong(s,input.value)).slice(0,5)):blank('給我一點線索，幫你翻歌本 ♡');
 if(id==='song-q'){filters.q=input.value;pages[isAdmin()?'songs':'book']=1;renderSongResults();}
 if(id==='player-query'){adminQuery=input.value;pages.players=1;$('#player-results').innerHTML=playerResults();}
 if(id==='ledger-query'){ledgerQuery=input.value;pages.ledger=1;const holder=document.createElement('div');holder.innerHTML=ledgerRows(null,true);$('#ledger-results').replaceWith(holder.querySelector('#ledger-results'));}
 if(id==='stats-day')$('#stats-result').innerHTML=statsHtml(stats(state,input.value+'T19:00:00+08:00'));
}catch(err){toast(err.message);}}
async function start(){if(demo){const catalog=await (await fetch('src/catalog.json')).json();full=get('demo')||migrateLegacy({songs:catalog,users:[],queue:[],crowns:[]});if(full.schemaVersion<3){put('before-v3',full);seedPreviewCrowns(full);full=upgradePlatform(full);}put('demo',full);}if(route==='admin'&&!admin)route='home';try{await refresh(true);}catch(e){header();$('#app').innerHTML=card('連線還沒準備好',`<p>${h(e.message)}</p><p class="muted">管理員完成 V2 部署設定後即可使用。現有正式資料沒有被改動。</p>${button('管理入口','admin')}`,true);}}
let lastHour=hourKey(clock());setInterval(()=>{const nextHour=hourKey(clock());if(nextHour!==lastHour&&!busy&&!$('#dialog').open&&!document.activeElement?.matches('input,textarea,select')){lastHour=nextHour;refresh(true).catch(()=>{});}if($('#hour'))$('#hour').innerHTML=hour();},1000);
setInterval(()=>{if(document.hidden||$('#dialog').open||document.activeElement?.matches('input,textarea,select')||demo||draft)return;refresh().catch(()=>{});},30000);
setInterval(()=>{if(route==='home'&&$('#photo-carousel')&&!document.hidden){photoIndex++;$('#photo-carousel').innerHTML=photoCarousel();}},8000);
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'home';if(next!==route)go(next).catch(e=>toast(e.message));});
function onBehalf(){modal('後台代播／自帶',select('playerId','玩家',playerOptions(),'')+select('songId','歌曲',state.songs.map(s=>[s.songId,s.title+'－'+s.artist]),'')+select('kind','使用方式',[['saved','完成演唱才扣存歌'],['live','現點（待確認禮物）']],'saved')+check('selfProvided','自帶：不列熱門／常聽，照常扣額度')+field('at','實際時間（留空為當下）','','datetime-local')+area('note','備註')+check('completed','補登已完成演唱')+'<p class="muted">補登過去的演唱，歸入當時統計，不占本小時提歌。</p><div id="proxy-cost"></div>',async f=>dispatch('onBehalf',{...formData(f),selfProvided:f.has('selfProvided'),at:isoInput(f.get('at')),completed:f.has('completed'),giftConfirmed:true}));let lastSongId='';const update=()=>{const current=$('#dialog [name=songId]').value;if(current===lastSongId)return;lastSongId=current;const chosen=song($('#dialog [name=songId]').value);$('#proxy-cost').innerHTML=chosen?shortSongOptions(chosen)+'<p>完成演唱扣 '+(Number(chosen.creditCost)===0.5?1:chosen.creditCost||1)+' 首</p>':'';};$('#modal-form').addEventListener('click',()=>setTimeout(update,0));}

start();

function jumpPage(input){if(!input)return;const n=Number(input.value),max=Number(input.max);if(!Number.isInteger(n)||n<1||n>max){toast('請輸入 1～'+max+' 的頁碼');return;}pages[input.dataset.pageKey]=n;render();}
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-page-key]')){e.preventDefault();jumpPage(e.target);}});
document.addEventListener('change',e=>{if(e.target.matches('[data-filter-tag]')){filters.tags=Array.from(document.querySelectorAll('[data-filter-tag]:checked'),x=>x.dataset.filterTag);pages={};render();}});

function select(name,label,values,value){if(!['playerId','songId'].includes(name))return nativeSelect(name,label,values,value);const match=values.find(v=>String(v[0])===String(value)),optional=label.includes('選填');return `<div class="entity-picker" data-entity-kind="${name}"><label>${h(label)}<input type="search" data-entity-query autocomplete="off" placeholder="${name==='playerId'?'搜尋玩家名稱、ID、曾用名':'搜尋歌名、歌手、語言、標籤'}" value="${h(match?.[0]?match[1]:'')}" aria-label="${h(label)}搜尋" ${optional?'':'required'}></label><input type="hidden" name="${name}" value="${h(value||'')}"><div class="entity-results"></div></div>`;}
function showEntityResults(box){const input=box.querySelector('[data-entity-query]'),q=input.value.trim(),kind=box.dataset.entityKind,rows=q?(kind==='playerId'?playerSearch(state,q):state.songs.filter(s=>matchesSong(s,q))):[];box.querySelector('.entity-results').innerHTML=q?(rows.slice(0,12).map(r=>button(h(kind==='playerId'?r.name+' · '+(r.ids.join('、')||'無平台 ID'):r.title+'－'+r.artist),'pickEntity',kind==='playerId'?r.playerId:r.songId,'entity-option')).join('')||'<small>沒有符合的資料</small>')+(rows.length>12?'<small>再輸入幾個字，縮小搜尋範圍 ♡</small>':''):'';}

document.addEventListener('submit',e=>{for(const box of e.target.querySelectorAll('.entity-picker')){const input=box.querySelector('[data-entity-query]');if((input.required||input.value.trim())&&!box.querySelector('[type=hidden]').value){e.preventDefault();e.stopImmediatePropagation();$('#dialog-error').textContent='請從搜尋結果點選正確的玩家或歌曲';input.focus();return;}}},true);
function seedPreviewCrowns(s){if(s.previewCrownsRestored)return;s.previewCrownsRestored=true;for(const [id,title,artist] of [['legacy-crown-1','三心愛意','不不玩家'],['legacy-crown-2','crazy 1 night','葵葵']]){if(!s.crowns.some(c=>c.id===id||c.title===title))s.crowns.push({id,title,artist,ownerName:'不不玩家',playerId:null,songId:null,tier:'至尊卡',fee:925000,price:55599,double:18188,months:0,activatedAt:null,expiresAt:null,legacyDisplay:true,note:'原網站冠歌：永久；生效時間未知。請核對綁定與款項，不自動設定生效時間。'});}}

function playerResults(){const p=paginate(playerSearch(state,adminQuery),'players');return `${p.rows.map(p=>`<div class="song"><div class="info"><b>${h(p.name)}${p.test?' 🧪':''}</b><small>${h(p.ids.join('、'))} · 💾 ${balance(state,p.playerId)}｜👑 ${state.crowns.filter(c=>c.playerId===p.playerId).length}｜🖼️ ${state.cards.filter(c=>c.playerId===p.playerId).length}｜🎤 ${state.queue.filter(q=>q.playerId===p.playerId&&q.status==='completed'&&!q.test).length}</small></div>${button('查看','playerDetail',p.playerId)}</div>`).join('')}${p.nav}`;}

function adminSongResults(){const p=paginate(filteredSongs(),'songs',20);return p.rows.map(s=>`<div class="song selectable-song ${selectedSongs.has(s.songId)?'is-selected':''}"><label class="song-check"><input type="checkbox" data-song-select="${h(s.songId)}" aria-label="選取 ${h(s.title)}" ${selectedSongs.has(s.songId)?'checked':''}></label><div class="info"><b>${h(s.title)}${s.new?' <span class="tag">✨ 新練</span>':''}</b><small>${h(s.artist)} · ${h(s.cat)} · ${plays(s)} 次</small><div class="song-tags">${s.tags?.length?s.tags.map(t=>`<span class="tag">${h(t)}</span>`).join(''):'<small class="subtle">尚未貼標籤</small>'}</div>${s.murmur?`<div class="subtle">💬 ${h(s.murmur)}</div>`:''}</div><div class="actions">${button('💬 碎碎念','editMurmur',s.songId)}${button('編輯','editSong',s.songId)}${button('刪除','deleteSong',s.songId,'tiny danger')}</div></div>`).join('')||blank('沒有符合的歌曲');}
function songBatchBar(){for(const id of selectedSongs)if(!song(id))selectedSongs.delete(id);const matches=filteredSongs(),visible=paginate(matches,'songs',20).rows,all=visible.length&&visible.every(s=>selectedSongs.has(s.songId));return `<div class="batch-toolbar"><label class="check-row"><input type="checkbox" data-select-song-page ${all?'checked':''} ${visible.length?'':'disabled'}>本頁全選</label><strong role="status" aria-live="polite">已選 ${selectedSongs.size} 首</strong>${button('選取搜尋結果（'+matches.length+'）','selectFilteredSongs','', 'tiny', matches.length?'':'disabled')}${button('取消選取','clearSongSelection','','tiny',selectedSongs.size?'':'disabled')}${button('批次編輯／貼標籤','bulkEditSongs','','tiny primary',selectedSongs.size?'':'disabled')}${songUndo&&songUndo.until>Date.now()?button('復原剛才的批次修改','undoSongBatch'):''}</div><small>可跨頁選取；搜尋不會清除已選歌曲。</small>`;}
function renderSongResults(){if(!$('#song-list'))return;const p=paginate(filteredSongs(),isAdmin()?'songs':'book',20);$('#song-list').innerHTML=(isAdmin()?adminSongResults():songRows(p.rows))+p.nav;if($('#song-batch-bar')){$('#song-batch-bar').innerHTML=songBatchBar();const rows=p.rows,checked=rows.filter(s=>selectedSongs.has(s.songId)).length,all=$('[data-select-song-page]');if(all)all.indeterminate=checked>0&&checked<rows.length;}}
document.addEventListener('change',e=>{if(e.target.matches('[data-song-select]')){const id=e.target.dataset.songSelect;e.target.checked?selectedSongs.add(id):selectedSongs.delete(id);renderSongResults();}if(e.target.matches('[data-select-song-page]')){for(const s of paginate(filteredSongs(),'songs',20).rows)e.target.checked?selectedSongs.add(s.songId):selectedSongs.delete(s.songId);renderSongResults();}});
const songEditFields=s=>({cat:s.cat,artistType:s.artistType,tags:s.tags||[],new:!!s.new,murmur:s.murmur||'',creditCost:s.creditCost??1});
function bulkEditSongs(){const ids=[...selectedSongs].filter(id=>song(id));if(!ids.length)return toast('先勾選要修改的歌曲');modal('批次編輯 '+ids.length+' 首歌曲',`<details class="notice"><summary>查看這次選取的 ${ids.length} 首</summary><div class="batch-selection">${ids.map(id=>h(song(id).title)+'－'+h(song(id).artist)).join('<br>')}</div></details><p class="muted">只改你指定的欄位，其餘資料保留。</p><div class="form-grid">${nativeSelect('tagMode','標籤處理',[['keep','不變'],['add','加上勾選標籤'],['remove','移除勾選標籤'],['replace','改成以下標籤'],['clear','清空標籤']],'keep')}${nativeSelect('cat','語言',[['','不變'],'華語','韓語','台語','其他'],'')}<div class="full chips batch-tag-options">${state.settings.tags.map(t=>check('tags',t).replace('name="tags"',`name="tags" value="${h(t)}"`)).join('')}</div>${field('customTags','其他標籤（逗號分開）')}${nativeSelect('artistType','歌手分類',[['','不變'],'女歌手','男歌手','團體','合唱','其他'],'')}${nativeSelect('new','新練歌曲',[['','不變'],['true','設為新練'],['false','取消新練']],'')}${nativeSelect('murmurMode','碎碎念',[['keep','不變'],['set','統一填寫'],['clear','清空']],'keep')}${field('creditCost','統一扣歌首數（空白不變）','','number','min="0.5" step="0.5"')}${field('murmur','統一的碎碎念','','text','maxlength="40"')}</div><div id="batch-preview" class="notice" aria-live="polite">尚未指定修改項目</div>`,async f=>{const data=bulkSongData(f,ids),before=ids.map(id=>({songId:id,...songEditFields(song(id))}));await dispatch('songsBulk',data);songUndo={before,after:ids.map(id=>({songId:id,...songEditFields(song(id))})),until:Date.now()+10000};clearTimeout(songUndoTimer);songUndoTimer=setTimeout(()=>{songUndo=null;if($('#song-batch-bar'))$('#song-batch-bar').innerHTML=songBatchBar();},10000);renderSongResults();toast('已更新 '+ids.length+' 首歌曲，可在 10 秒內復原');});const form=$('#modal-form');form.addEventListener('change',()=>updateBulkPreview(form,ids));form.addEventListener('input',e=>{if(!e.isComposing)updateBulkPreview(form,ids);});}
function bulkSongData(f,ids){const data={songIds:ids,tagMode:f.get('tagMode'),tags:[...f.getAll('tags'),...list(f.get('customTags'))]};for(const k of ['cat','artistType'])if(f.get(k))data[k]=f.get(k);if(f.get('creditCost'))data.creditCost=Number(f.get('creditCost'));if(f.get('new'))data.new=f.get('new')==='true';if(f.get('murmurMode')!=='keep')data.murmur=f.get('murmurMode')==='clear'?'':f.get('murmur');return data;}
function updateBulkPreview(form,ids){const f=new FormData(form);if((f.getAll('tags').length||f.get('customTags').trim())&&f.get('tagMode')==='keep'){form.elements.tagMode.value='add';f.set('tagMode','add');}const d=bulkSongData(f,ids),parts=[];if(d.tagMode!=='keep')parts.push(({add:'加上標籤：',remove:'移除標籤：',replace:'改成標籤：',clear:'清空標籤'})[d.tagMode]+(d.tagMode==='clear'?'':d.tags.join('、')));if(d.creditCost)parts.push('扣歌首數：'+d.creditCost);if(d.cat)parts.push('語言：'+d.cat);if(d.artistType)parts.push('歌手分類：'+d.artistType);if('new'in d)parts.push(d.new?'設為新練歌曲':'取消新練');if('murmur'in d)parts.push(d.murmur?'碎碎念：'+d.murmur:'清空碎碎念');$('#batch-preview').textContent=parts.length?'將修改 '+ids.length+' 首：'+parts.join('；'):'尚未指定修改項目';}
async function undoSongBatch(){if(!songUndo||songUndo.until<Date.now())return toast('復原時間已過');const undo=songUndo;await dispatch('restoreSongEdits',{before:undo.before,after:undo.after});songUndo=null;clearTimeout(songUndoTimer);renderSongResults();toast('已復原剛才的批次修改');}

function editStreamer(id){const r=state.streamers.find(r=>r.id===id)||{};modal(id?'編輯主播':'新增主播',field('display_name','主播名稱',r.display_name||'','text','required')+field('slug','網址名稱（英文）',r.slug||'','text','required')+field('home_title','首頁名稱',r.home_title||'')+field('subtitle','副標題',r.subtitle||'')+field('avatar_url','頭像網址',r.avatar_url||'')+field('banner_url','橫幅網址',r.banner_url||'')+area('description','介紹',r.description||'')+check('active','開放主播頁',r.active!==false),async f=>dispatch('streamer',{...formData(f),id:r.id,active:f.has('active')}));}
document.addEventListener('change',e=>{if(e.target.name==='streamer-switch'){const u=new URL(location.href);u.searchParams.set('streamer',e.target.value);location.href=u.href;}if(e.target.matches('[data-queue-select]')){e.target.checked?selectedQueue.add(e.target.dataset.queueSelect):selectedQueue.delete(e.target.dataset.queueSelect);}});
document.addEventListener('input',e=>{if(e.target.matches('[data-pair-filter]'))for(const label of document.querySelectorAll('.pair-options label'))label.hidden=!label.textContent.toLocaleLowerCase().includes(e.target.value.toLocaleLowerCase());});

document.addEventListener('input',e=>{if(e.target.matches('[data-short-filter]'))for(const option of document.querySelectorAll('[name=pairSongId] option'))option.hidden=!!option.value&&!option.textContent.toLocaleLowerCase().includes(e.target.value.toLocaleLowerCase());});

document.addEventListener('input',e=>{if(e.target.matches('[data-room-filter]'))for(const button of document.querySelectorAll('.room-options button'))button.hidden=!button.textContent.toLocaleLowerCase().includes(e.target.value.toLocaleLowerCase());});


async function loadEvents(){const holder=$('#event-list');if(!holder)return;try{if(demo||draft){holder.innerHTML=blank('永久操作歷史於正式同步時由伺服器記錄。');return;}const r=await api({op:'events',page:eventPage});if(holder!==$('#event-list'))return;const labels={players:'玩家',songs:'歌曲',ledger:'存歌',queue:'點歌',crowns:'冠歌',cards:'卡片',wishes:'許願',settings:'設定',meta:'主播設定'};holder.innerHTML=r.rows.map(x=>'<details class="notice"><summary>'+h(time(x.created_at))+' · '+h(labels[x.entity_kind]||x.entity_kind)+' · '+h(x.action)+'</summary><p>操作者：'+h(x.actor_player_id?playerName(x.actor_player_id):'管理端')+'<br>實際時間：'+h(time(x.effective_at))+'</p><pre class="event-detail">'+h(JSON.stringify({修改前:x.before_data,修改後:x.after_data},null,2))+'</pre></details>').join('')||blank('尚無新操作紀錄');holder.innerHTML+='<div class="actions">'+button('上一頁','eventPage','-1','tiny',eventPage?'':'disabled')+'<small>第 '+(eventPage+1)+' 頁</small>'+button('下一頁','eventPage','1','tiny',r.hasMore?'':'disabled')+'</div>';}catch(e){holder.textContent=e.message;}}
function recordTime(table,id){const row=state[table].find(x=>x.id===id),labels={at:'提出／存歌時間',acceptedAt:'收到禮物／確認時間',completedAt:'完成演唱時間',cancelledAt:'取消時間',storedAt:'轉存時間',activatedAt:'生效時間',expiresAt:'到期時間',startsAt:'開始時間'},keys=({queue:['at','acceptedAt','completedAt','cancelledAt','storedAt'],ledger:['at'],crowns:['activatedAt','expiresAt'],cards:['startsAt','expiresAt'],wishes:['at']})[table].filter(k=>row[k]||k==='at');modal('調整實際時間','<p>登記時間：'+h(time(row.created_at||row.createdAt))+'（保留不變）</p>'+keys.map(k=>field(k,labels[k],dateInput(row[k]),'datetime-local','required')).join('')+area('note','備註',row.note||''),async f=>dispatch('recordTime',{table,id,times:Object.fromEntries(keys.map(k=>[k,isoInput(f.get(k))])),note:f.get('note')}));}
function allocateDialog(id){const old=state.ledger.find(l=>l.id===id);modal('收到歌單：分配現點／存歌',select('playerId','玩家',playerOptions(),old?.playerId||'')+field('total','收到總首數',old?.amount||3,'number','min="0.5" step="0.5" required '+(old?'readonly':''))+field('stored','保留存歌首數',old?.amount||2,'number','min="0" step="0.5" required')+field('effective_at','實際收到時間',dateInput(old?.at||clock()),'datetime-local','required')+area('note','備註',old?.note||'')+check('openingBalance','歷史／初始存歌（不計當日收到）',old?.openingBalance||old?.note==='初始存歌')+'<p class="muted">存歌首數＋下方現點用額必須等於總首數。已收到禮物的現點直接排入待唱；選擇已唱則補登完成。</p><div id="allocation-rows"></div>'+button('＋加入現點歌曲','allocationRow'),async(f,form)=>{const items=[...form.querySelectorAll('.allocation-row')].map(row=>({songId:row.querySelector('[name=songId]').value,pairSongId:row.querySelector('[name=pairSongId]')?.value||'',completed:row.querySelector('[name=completed]').checked}));await dispatch('allocate',{...formData(f),ledgerId:old?.id,items,effective_at:isoInput(f.get('effective_at')),openingBalance:f.has('openingBalance')});});}
function addAllocationRow(){const div=document.createElement('div');div.className='allocation-row notice';div.innerHTML=select('songId','現點歌曲',state.songs.map(s=>[s.songId,s.title+'－'+s.artist]),'')+'<div class="allocation-cost"></div>'+check('completed','此首已完成演唱')+button('移除此列','removeAllocationRow');$('#allocation-rows').append(div);let previous='';div.addEventListener('click',()=>setTimeout(()=>{const id=div.querySelector('[name=songId]').value;if(id===previous)return;previous=id;const s=song(id);div.querySelector('.allocation-cost').innerHTML=s?shortSongOptions(s)+'<p>使用 '+(Number(s.creditCost)===0.5?1:s.creditCost||1)+' 首額度</p>':'';},0));}

notifications.refresh().catch(()=>{});

async function streamerAccounts(){if(!isSuperAdmin())return;const r=demo?{accounts:[]} :await api({op:'streamerAccounts'});modal('主播帳號與密碼','<p>玩家帳號全站共用；主播登入只管理自己的資料。設定或停用後，該主播現有管理登入會失效。</p>'+state.streamers.map(room=>{const a=r.accounts.find(a=>a.streamer_id===room.id);return '<div class="notice"><b>'+h(room.display_name)+'</b> · '+(a?.enabled?'已啟用':'尚未啟用')+' '+button('設定密碼／啟用','streamerCredentials',room.id)+'</div>';}).join(''));}
async function streamerCredentials(id){if(!isSuperAdmin())return;const room=state.streamers.find(r=>r.id===id);if(!room)return;modal(room.display_name+' · 主播登入',field('password','新密碼（已設定者留空可保留）','','password','minlength="4" maxlength="72" autocomplete="new-password"')+check('enabled','啟用主播登入',true),async f=>{if(demo)throw Error('請在正式總管理設定');await api({op:'setStreamerAccount',streamer:room.slug,password:f.get('password'),enabled:f.has('enabled')});toast('主播登入設定已儲存');});}
